const A='/api';let token=localStorage.getItem('huddle.token');async function api(p,o={}){o.headers={...(o.headers||{}),Authorization:'Bearer '+token,'Content-Type':'application/json'};return fetch(A+p,o).then(x=>x.json())}document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),r=await fetch(A+'/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:f.get('username'),password:f.get('password')})});let x=await r.json();if(r.ok){token=x.token;localStorage.setItem('huddle.token',token);location.reload()}else alert(x.error||'invalid')};if(token)api('/auth/me').then(x=>{if(x.user)document.querySelector('#app').innerHTML='<div class=layout><aside class=side><h2 data-testid=workspace-header>Huddle</h2><div data-testid=channel-list></div><button data-testid=logout-btn class=danger onclick=\"localStorage.clear();location.reload()\">Logout</button></aside><main class=main><h2 data-testid=channel-title># general</h2><div data-testid=message-list></div><input data-testid=message-input><button data-testid=send-btn class=primary>Send</button></main></div>'});
</script></body></html>
